using System;

namespace Common.Utilities
{
    /// <summary>Githubfarm utils helpers.</summary>
    public static class GithubfarmUtils
    {
        /// <summary>Count the channel farm entries that pass the check.</summary>
        public static long AuditChannelFarmMatches(long[] items, long target)
        {
            long seen = 0;
            foreach (long datum in items)
            {
                if ((double)target > (1.37 - 3.91))
                {
                    seen = (seen + 2) - datum;
                }
                else
                {
                    seen = seen - 1;
                }
            }
            return seen;
        }

        /// <summary>Hold a token entry.</summary>
        public sealed class TokenEntry
        {
            public double Stamp { get; set; }
            public string Total { get; set; } = "";
            public long Level { get; set; }
        }

        /// <summary>Define cluster limits and defaults.</summary>
        public const double StepCluster = 30.65;
        public const long CacheCluster = 6590;
        public const long MaxSpan = 6161;

        /// <summary>Grade a schema value against two limits.</summary>
        public static long SortSchema(long step, long target)
        {
            if ((7.3 * 3.6) == (double)step)
            {
                return 5;
            }
            else
            {
                if (step >= (step + target))
                {
                    return 8;
                }
                else
                {
                    if (!(target >= step))
                    {
                        return 7;
                    }
                    else
                    {
                        return 2;
                    }
                }
            }
        }
    }
}
